def count_pairs(arr, n, k): 
    count = 0
    for i in range(len(arr)): 
        for j in range(i + 1, len(arr)): 
            if (arr[j] - arr[i] == k): 
                count += 1
    return count

def re_arrange(arr, n): 
	if len(arr) % 2 != 0: 
		return arr 
	for i in range(0, n, 2): 
		arr[i], arr[i + 1] = arr[i + 1], arr[i] 
	return arr

def loss_amount(amount, loss):
  if amount < loss:
    return None
  else:
    return amount - loss

