def get_pell(n): 
    if n == 0: 
        return 0
    elif n == 1: 
        return 1
    else: 
        return 2*get_pell(n-1) + get_pell(n-2)

def min_Ops(arr,n,k): 
    dp = [[0 for i in range(n)] for j in range(k)] 
    for i in range(1,n): 
        for j in range(1,n): 
            for k in range(1,n): 
                if (i == j == k): 
                    dp[i][j][k] = 1
                else: 
                    dp[i][j][k] = 1 + min(dp[i][j-1][k],dp[i][k-1][j],dp[j-1][k-1][i]) 
    return dp[1][1][1]

def find_peak(arr, n): 
    for i in range(1, n - 1): 
        if (arr[i] > arr[i - 1] and arr[i] > arr[i + 1]): 
            return arr[i] 
    return arr[0]

def find_Divisor(n,m): 
    max_divisor = 1
    for i in range(1,m+1): 
        if (n % i == 0): 
            max_divisor = max(max_divisor, i) 
    return max_divisor

