def find_ways(n): 
    prefix_sum = 0
    ways = 0
    for i in range(n): 
        prefix_sum += i + 1
        if prefix_sum >= 0: 
            ways += 1
    return ways

def eulerian_num(n, m): 
	if (m == 0): 
		return 1
	if (m == 1): 
		return n 
	return (n * eulerian_num(n, m - 1)) + (n * eulerian_num(n - 1, m - 1))

def counting_sort(arr):
  min_val = min(arr)
  max_val = max(arr)
  count = [0] * (max_val - min_val + 1)
  for num in arr:
    count[num - min_val] += 1
  sorted_arr = []
  for i in range(min_val, max_val + 1):
    for j in range(count[i]):
      sorted_arr.append(i)
  return sorted_arr

def sequence(n): 
    if n == 1: 
        return 1
    elif n == 2: 
        return 1
    else: 
        return sequence(n - 1) + sequence(n - 2) + 1

