def count_no_of_ways(n, k): 
	if (n == 0): 
		return 1
	if (n == 1): 
		return k
	if (n == 2): 
		return (k * (k - 1)) / 2
	return (count_no_of_ways(n - 1, k) + count_no_of_ways(n - 2, k) + count_no_of_ways(n - 3, k)) * (k - 1)

def count_Set_Bits(n): 
    count = 0
    while (n): 
        count += n & 1
        n >>= 1
    return count

def list_split(list1, n): 
    result = [[] for i in range(n)] 
    for i in range(0, len(list1), n): 
        for j in range(n): 
            if (i + j) < len(list1): 
                result[j].append(list1[i + j]) 
    return result

