def minimum_Length(str1): 
    str1 = list(str1) 
    min_length = 0
    for i in range(len(str1)): 
        count = 0
        for j in range(i + 1, len(str1)): 
            if str1[i] == str1[j]: 
                count += 1
        if count == 1: 
            min_length = min(min_length, len(str1) - i) 
    return min_length

def sum_div(n): 
